INSERT INTO `locales_spell` (`entry`, `name_loc1`, `description_loc1`) VALUES
(14183, '사전 계획', '사용 시, 대상에게 $s1 콤보 포인트를 추가합니다. 추가된 콤보 포인트는 $d 이내에 사용하거나 추가해야 하며, 그렇지 않으면 소멸됩니다.'),
(14185, '준비', '이 능력을 활성화하면 다른 도적 능력의 재사용 대기시간이 즉시 완료됩니다.'),
(14198, '짐승 사냥 27', '야수와 싸울 때 공격력이 $s1 증가합니다.'),
(14199, '사모플란지 제작 설명서', '표지와 5개의 페이지를 합쳐 사모플란지 매뉴얼을 만드세요.'),
(14200, '사슬 화살', '번개를 발사하여 근처의 다른 적에게 번개가 뻗어나가게 합니다. 이 주문은 최대 $x1명의 대상에게 영향을 미치며, 각 대상에게 자연 피해를 입힙니다.'),
(14209, '서명', '닉스 스프로킷스프링에게 고블린 공학 지식을 영원히 비밀로 지키겠다고 맹세하는 서약서에 서명하십시오.'),
(14210, '서명', '오글소프 오브노티쿠스에게 그놈 공학에 대한 지식을 영원히 비밀로 유지하겠다고 맹세하는 서약서에 서명하십시오.'),
(14227, '서명', '팅크마스터 오버스파크에게 그놈 공학에 대한 지식을 영원히 비밀로 유지하겠다고 맹세하는 서약서에 서명하십시오.'),
