INSERT INTO `locales_spell` (`entry`, `name_loc1`, `description_loc1`) VALUES
(24838, '그림자 볼트 회오리', '적에게 어둠의 마법 화살을 발사하여 그림자 피해를 입힙니다.'),
(24852, '자연 치명타 확률 증가', '자연 주문으로 치명타를 입힐 확률을 $s1% 증가시킵니다.'),
(24854, '마나의 샘 토템', '시전자의 발밑에 생명력 $s1의 마나 샘 토템을 소환합니다. 이 토템은 $d의 지속 시간 동안 $24853t1초마다 $24853a1야드 이내의 파티원들에게 $24853s1의 마나를 회복시켜 줍니다.'),
(24855, '도안: 불꽃 팔찌', '스핏화염 브레이서를 제작하는 방법을 알려줍니다.'),
(24856, '도안: 불꽃 장갑', '스핏화염 건틀릿 제작법을 알려줍니다.'),
(24857, '비전 폭발', '적에게 마법 공격을 가하여 일반 피해에 $s2의 추가 피해를 입히고 적을 뒤로 밀쳐냅니다.'),
(24859, '도안: 불꽃 흉갑', '스핏화염 흉갑 제작법을 알려줍니다.'),
(24860, '도안: 모래추적자 팔찌', '샌드스토커 팔찌 제작법을 알려줍니다.'),
(24861, '도안: 모래추적자 장갑', '모래추적자 장갑 제작법을 알려줍니다.'),
(24862, '도안: 모래추적자 흉갑', '모래추적자 흉갑 제작법을 알려줍니다.'),
(24866, '고양이의 민첩성', '고양이 변신 상태에서 야외에 있을 때 이동 속도가 $s1% 증가하고, 고양이 변신 상태에서 회피 확률이 $24864s1% 증가합니다.'),
(24874, '불 속성 소환 문장 제작', '견고한 가죽 1개와 불꽃꽃 1개를 조합하여 \'불의 소환 문장\'을 제작하세요.'),
(24885, '공기 속성 소환 문장 제작', '견고한 가죽 1개와 공기 정령 1개를 조합하여 \'천둥의 소환 문장\'을 제작하세요.'),
(24887, '대지 속성 소환 문장 제작', '견고한 가죽 1개와 단단한 돌 1개를 조합하여 \'대지의 소환 문장\'을 제작하세요.'),
(24888, '소환의 문장 생성: 물', '견고한 가죽 1개와 마법의 물 1개를 조합하여 \'물의 유혹 문장\'을 만드세요.'),
(24889, '소환의 인장 생성: 불', '어둠의 룬 1개와 불꽃꽃 5개를 조합하여 \'불의 유혹 문장\'을 만드세요.'),
(24890, '소환의 인장 생성: 공기', '어둠의 룬 1개와 정령의 공기 5개를 조합하여 \'천둥의 유혹 문장\'을 만드세요.'),
(24891, '소환의 인장 생성: 흙', '어둠의 룬 1개와 단단한 돌 5개를 조합하여 \'돌의 유혹 문장\'을 만드세요.'),
(24892, '소환의 인장 생성: 물', '어둠의 룬 1개와 마법의 물 5개를 조합하여 \'물의 유혹 문장\'을 만드세요.'),
(24895, '소환의 홀 생성: 불', '진실의 지팡이 1개와 불꽃꽃 20개를 조합하여 소환의 홀: 불을 제작하세요.'),
(24896, '소환의 홀 생성: 공기', '진실의 지팡이 1개와 정령의 공기 20개를 조합하여 소환의 홀: 천둥을 제작하세요.'),
(24897, '소환의 홀 생성: 흙', '진실의 지팡이 1개와 조밀한 돌 20개를 조합하여 소환의 홀: 돌을 제작하세요.'),
(24898, '소환의 홀 생성: 물', '진실의 지팡이 1개와 마법의 물 20개를 조합하여 소환의 홀: 물을 제작하세요.'),
(24908, '도안: 룬이 새겨진 스티지안 레깅스', '룬이 새겨진 스티지안 레깅스를 만드는 방법을 알려줍니다.'),
(24909, '패턴: 룬이 새겨진 스티지안 벨트', '룬이 새겨진 스티지안 벨트를 만드는 방법을 알려줍니다.'),
(24911, '패턴: 룬이 새겨진 스티지안 부츠', '룬이 새겨진 스티지안 부츠를 만드는 방법을 알려줍니다.'),
(24915, '설계도: 다크룬 건틀릿', '다크룬 건틀릿을 만드는 방법을 알려줍니다.'),
(24916, '설계도: 다크룬 투구', '다크룬 투구를 만드는 방법을 알려줍니다.'),
(24917, '설계도: 다크룬 흉갑', '다크룬 흉갑을 만드는 방법을 알려줍니다.'),
(24921, '지팡이 강화', '지팡이 공격력 +$s1.'),
(24930, '할로윈 사탕', '맛있는 할로윈 간식을 즐겨보세요! 상하기 전에 빨리 먹어 버리는 게 좋을 거야...'),
(24933, '대포', '앞쪽 $a1야드 이내에 있는 가장 가까운 톤크에게 포탄을 발사합니다. $s1의 피해를 줍니다.'),
(24939, '멀키', '시전자가 해제할 때까지 $s1 $lMurky:Murky;를 소환하여 시전자를 따라다니게 합니다.'),
(24941, '패턴: 검은 새끼용 튜닉', '검은 새끼용 튜닉 제작법을 알려줍니다.'),
(24947, '치유', '모든 생명력을 회복합니다.'),
(24948, '방어 상태 2', '방어, 회피 또는 막기에 성공하면 발동합니다.'),
(24973, '악취 폭탄 청소', '사우스쇼어에서 발견한 악취 폭탄을 제거합니다.'),
(24993, '산성 폭발', '적에게 $s1의 자연 피해를 주는 산성 공격을 가합니다.'),
(24994, '공격력 - 야성 (+154)', '고양이, 곰, 흉포한 곰, 달빛야수 변신 시 공격력이 $s1 증가합니다.'),
(25003, '박격포', '박격포를 발사하여 $a1야드 떨어진 곳에 떨어뜨리고 $27745a1야드 내의 모든 탱크에 $27745s1의 피해를 입힙니다.'),
(25018, '머키', '마우스 오른쪽 버튼을 클릭하여 무르키를 소환하고 해제하세요.'),
(25019, '눈보라', '선택한 지역 내 모든 적에게 $d초 동안 지속되는 눈보라를 소환하여 $t1초마다 $s1의 냉기 피해를 입힙니다.'),
(25021, '연쇄 번개', '적에게 번개를 내리쳐 근처의 다른 적에게 번개가 뻗어나가게 합니다. 이 주문은 최대 $x1명의 대상에게 영향을 미치며, 연속되는 대상마다 더 큰 자연 피해를 입힙니다.'),
(25024, '지뢰 투하', '지뢰를 설치합니다. 지뢰는 작동하는 데 3초가 걸리며, 작동되면 반경 $25099a1야드 내의 모든 톤크에게 $25099s1의 피해를 줍니다.'),
(25025, '대지 충격', '적에게 충격파를 가해 자연 피해를 입히고 $d 동안 주문 시전을 중단시킵니다.'),
(25026, 'MG 터렛 활성화', '초당 마나 10 소모.\r\n$t1초마다 $25032a1야드 이내의 가장 가까운 적 탱크에게 자동으로 사격을 가하여 발당 $25032s1의 피해를 줍니다.'),
(25027, '화염방사기', '초당 마나 10 소모.\r\n$25029a1야드 이내의 전방 모든 탱크에게 $t1초마다 $25029s1의 피해를 줍니다. 또한 이동 속도를 $25029s2% 감소시키고 $25029d 동안 초당 $25029s3의 피해를 줍니다.'),
(25028, '화염 폭발', '적에게 화염 피해를 입힙니다.'),
(25033, '번개 구름', '$d초 동안 지속되는 번개 구름을 생성하여 선택한 지역의 모든 적에게 $s1의 자연 피해를 입히고 $t2초마다 $s2의 추가 피해를 입힙니다.'),
(25034, '포크드 라이트닝', '시전자 전방 원뿔형 범위 내 적들에게 자연 피해를 입힙니다.')
INSERT INTO `locales_spell` (`entry`, `name_loc1`, `description_loc1`) VALUES
(25036, '블록 값 12', '방패의 방어력을 $s1만큼 증가시킵니다.'),
(25052, '산성 침 뱉기', '적에게 자연 피해를 입힙니다.'),
(25054, '신성한 일격', '적을 강타하여 신성 피해를 입힙니다.'),
(25055, '비전의 화살', '적에게 마법 화살을 던져 비전 피해를 입힙니다.'),
(25060, '상승 기류', '시전자 전방 원뿔형 범위 내의 적들을 공격하여 뒤로 밀쳐냅니다.'),
(25064, '어둠 피해 증가 20', '암흑 마법 및 효과로 입히는 피해량을 최대 $s1까지 증가시킵니다.'),
(25065, '화재댐 20 증가', '화염 마법 및 효과로 입히는 피해량을 최대 $s1까지 증가시킵니다.'),
(25066, '얼음 댐 20 증가', '냉기 마법 및 효과로 입히는 피해량을 최대 $s1까지 증가시킵니다.'),
(25067, '치유량 30 증가', '주문 및 효과로 인한 치유량을 최대 $s1까지 증가시킵니다.'),
(25072, '장갑 마법 부여 - 위협 감소', '장갑에 모든 공격 및 마법으로 인한 위협 수준을 2% 증가시키는 마법을 영구적으로 부여합니다.'),
(25073, '장갑 마법 부여 - 그림자의 힘', '장갑에 암흑 피해량을 최대 20까지 증가시키는 마법을 영구적으로 부여합니다.'),
(25074, '장갑 마법 부여 - 냉기 공격력', '장갑에 냉기 피해량을 최대 20까지 증가시키는 마법을 영구적으로 부여합니다.'),
(25078, '장갑 마법 부여 - 화염 공격력', '장갑에 화염 공격력을 최대 20까지 영구적으로 증가시키는 마법을 부여합니다.'),
(25079, '장갑 마법 부여 - 치유력', '장갑에 시전자의 치유 마법 공격력을 최대 30까지 영구적으로 증가시키는 마법을 부여합니다.'),
(25080, '장갑 마법 부여 - 뛰어난 민첩성', '장갑에 영구적으로 마법을 부여하여 민첩성을 15만큼 증가시킵니다.'),
(25081, '망토 마법 부여 - 강화된 화염 저항력', '망토에 영구적으로 마법을 부여하여 화염 저항력을 15만큼 증가시킵니다.'),
(25082, '망토 마법 부여 - 강화된 자연 저항력', '망토에 영구적으로 마법을 부여하여 자연 저항력을 15만큼 증가시킵니다.'),
(25083, '망토 마법 부여 - 은신', '망토에 영구적으로 마법을 부여하여 은신 확률을 증가시킵니다.'),
(25084, '망토 마법 부여 - 은밀함', '망토에 영구적으로 마법을 부여하여 착용자가 몬스터에게 발생시키는 위협 수준을 2%만큼 감소시킵니다.'),
(25085, '밝은 모닥불', '주변 아군의 사기를 8만큼 증가시키고 요리할 수 있게 하는 모닥불을 피웁니다.'),
(25086, '마법 부여 망토 - 회피', '망토에 영구적으로 마법을 부여하여 회피 확률을 1%만큼 증가시킵니다.'),
(25087, '주문: 장갑 마법 부여 - 위협', '장갑에 영구적으로 마법을 부여하여 착용자가 몬스터에게 발생시키는 위협 수준을 증가시키는 방법을 알려줍니다.'),
(25088, '주문: 장갑 마법 부여 - 그림자 힘', '주문과 능력으로 입히는 암흑 피해를 20만큼 영구적으로 증가시키는 마법 부여를 장갑에 적용하는 방법을 알려줍니다.'),
(25089, '주문: 장갑 마법 부여 - 냉기 힘', '주문과 능력으로 입히는 냉기 피해를 20만큼 영구적으로 증가시키는 마법 부여를 장갑에 적용하는 방법을 알려줍니다.'),
(25090, '주문: 장갑 마법 부여 - 화염 힘', '주문과 능력으로 입히는 화염 피해를 20만큼 영구적으로 증가시키는 마법 부여를 장갑에 적용하는 방법을 알려줍니다.'),
(25091, '주문: 장갑 마법 부여 - 치유력', '주문과 능력으로 주는 치유량을 30만큼 영구적으로 증가시키는 마법 부여 장갑을 만드는 방법을 알려줍니다.'),
(25092, '주문: 장갑 마법 부여 - 뛰어난 민첩성', '민첩성을 15만큼 영구적으로 증가시키는 마법 부여 장갑을 만드는 방법을 알려줍니다.'),
(25093, '공식: 망토 마법 부여 - 화염 저항력 증가', '화염 저항력을 15만큼 영구적으로 증가시키는 망토를 만드는 방법을 알려줍니다.'),
(25094, '공식: 망토 마법 부여 - 자연 저항력 증가', '자연 저항력을 15만큼 영구적으로 증가시키는 마법 부여 망토를 만드는 방법을 알려줍니다.'),
(25095, '공식: 망토 마법 부여 - 은신', '은신 능력을 영구적으로 증가시키는 마법 부여 망토를 만드는 방법을 알려줍니다.'),
(25096, '공식: 망토 마법 부여 - 교활함', '착용자가 몬스터에게 위협적인 정도를 2%만큼 감소시키는 마법 부여 망토를 만드는 방법을 알려줍니다.'),
(25097, '공식: 망토 마법 부여 - 회피', '회피 확률을 1%만큼 증가시키는 마법 부여 망토를 만드는 방법을 알려줍니다.'),
(25104, '플레이어 소환', '적 플레이어를 소환합니다.'),
(25109, '주문 피해 증가 8', '마법 주문 및 효과로 인한 피해량과 치유량을 최대 $s1까지 증가시킵니다.'),
(25110, '주문 피해 16 증가', '마법 주문 및 효과로 인한 피해량과 치유량을 최대 $s1까지 증가시킵니다.'),
(25111, '주문 피해 24 증가', '마법 주문 및 효과로 인한 피해량과 치유량을 최대 $s1까지 증가시킵니다.'),
(25113, '주문 피해 36 및 1% 증가 치명타', '마법 주문 및 효과로 인한 피해량과 치유량을 최대 $s1까지 증가시킵니다. 또한 주문의 치명타 확률을 $s3% 증가시킵니다.'),
(25114, '마나 재생 증가', '$t1초마다 마나 $s1을 회복합니다.'),
(25115, '마나 재생 증가', '$t1초마다 마나 $s1을 회복합니다.'),
(25116, '마나 재생 및 치유량 증가', '$t1초마다 마나 $s1을 회복하고 치유량을 $s2만큼 증가시킵니다.'),
(25117, '하급 마법사 오일', '대상 무기에 적용 시 주문 공격력이 최대 8까지 증가합니다. 30분 동안 지속됩니다.'),
(25118, '하급 마나 오일', '대상 무기에 적용 시 시전자의 마나를 5초마다 4씩 회복합니다. 30분 동안 지속됩니다.'),
(25119, '하급 마법사 오일', '대상 무기에 적용 시 주문 공격력이 최대 16까지 증가합니다. 30분 동안 지속됩니다.'),
(25120, '하급 마나 오일', '대상 무기에 적용 시 시전자의 마나를 5초마다 8씩 회복합니다. 30분 동안 지속됩니다.'),
(25121, '마법사 오일', '대상 무기에 적용 시 주문 공격력이 최대 24까지 증가합니다. 30분 동안 지속됩니다.'),
(25122, '찬란한 마법사 오일', '대상 무기에 적용 시 주문 공격력을 최대 36까지 증가시키고 주문 치명타 확률을 1% 증가시킵니다. 30분 동안 지속됩니다.'),
(25123, '찬란한 마나 오일', '대상 무기에 적용 시 시전자의 마나를 5초마다 12 회복시키고 치유 주문의 효과를 최대 25까지 증가시킵니다. 30분 동안 지속됩니다.'),
(25124, '하급 마법사 오일', '하급 마법사 기름을 생성합니다.'),
(25125, '하급 마나 오일', '하급 마나 기름을 생성합니다.'),
(25126, '하급 마법사 오일', '하급 마법사 오일을 생성합니다.')
