INSERT INTO `locales_spell` (`entry`, `name_loc1`, `description_loc1`) VALUES
(30156, '히포그리프 새끼', '페랄라스에 하피가 침입한 후, 여러 히포그리프 둥지가 공격받았습니다. 수백 마리의 새끼 히포그리프가 고아가 되었고, 사르도르 섬의 드루이드들이 이들을 돌보고 있습니다.'),
(30161, '보라색 불꽃놀이', '하늘로 불꽃놀이 폭죽을 쏘아 올려 수천 개의 보라색 별이 터지게 합니다.'),
(30163, '보라색 로켓 복제품', '발사기에 불꽃놀이를 발사합니다.'),
(30194, '산성폭탄', '해당 지역의 적에게 자연 피해를 입힙니다.'),
(30197, '충돌하다', '$s1 물리 피해를 위해 적을 폭파합니다.'),
(30198, '떨어지는 잔해', '$r1 반경 내의 모든 대상이 $s1 물리 피해를 입게 합니다.'),
(30201, '케이브 인', '$a1 야드 내의 모든 대상에게 $s1 물리 피해를 입힙니다.'),
(30203, '기둥 차단기', '땅을 밟아 주변 적들에게 $s1 피해를 주고 뒤로 밀쳐냅니다.'),
(30204, '골드로 변환', '$a1 반경 내의 모든 적을 죽입니다.'),
(30205, '요금', '에젤은 적을 향해 돌격할 준비를 합니다.'),
(30206, '요금', '적에게 돌격하세요.'),
(30207, '암흑 충격', '즉시 암흑 마법으로 적을 채찍질해 암흑 피해를 입힙니다.'),
(30208, '애완동물 되살리기', '생명력과 마나의 $s1%로 죽은 생명체를 되살립니다.'),
(30239, '바다거북 등껍질', '바다거북 등껍질 2개를 결합하여 바다거북 등껍질 견갑을 만드세요.'),
(30281, '저주 제거', '아군에게 걸린 $s1 $lcurse:curses; 효과를 해제합니다.'),
(30440, '주문 적중 확률 증가', '도발과 도전의 외침의 적중률을 $s1% 증가시킵니다.'),
(30441, '주문 적중 확률 증가', '으르렁거림 공격의 명중률을 $s1% 향상시킵니다.'),
(30732, '벌레 휩쓸기', '시전자 전방 원뿔형 범위 내 적에게 $s1의 피해를 입히고 뒤로 밀쳐냅니다.'),
