INSERT INTO `locales_spell` (`entry`, `name_loc1`, `description_loc1`) VALUES
(51143, '압도적인 힘의 유적', '$d를 위해 당신을 보호할 하급 비전 정령을 소환합니다. 이 정령이 살아 있는 동안 마법 주문 및 효과로 인한 피해와 치유량이 최대 $51142s1만큼 증가합니다.'),
(51146, 'Shieldrender Talisman 패시브', '물리 공격으로 인해 다음 $51145n 물리 공격이 방어구를 무시할 확률이 있습니다. $51145d 지속됩니다.'),
(51147, '충격', '충격적인 힘으로 적에게 충격을 가해 자연 피해를 입힙니다.'),
(51148, '정전기의 토템', '번개 화살은 $h%의 확률로 적에게 충격을 주어 $51147s1 자연 피해를 입힙니다. 이 효과는 위협을 생성하지 않습니다.'),
(51149, '빛의 성서', '성스러운 빛과 성스러운 일격의 치명타 적중률이 $s1%만큼 증가합니다.'),
(51150, '정점 포식자의 우상', '사기의 포효의 분노 비용이 $/10;s1만큼 감소합니다.'),
(51151, '주문 피해 감소 5', '받는 모든 주문 피해를 $s1%만큼 감소시킵니다.'),
(51152, '독극물', '독 +$s1.'),
(51158, '전투 체력 재생 5', '전투 중에 체력 재생의 $s1%가 작동하도록 허용합니다.'),
(51159, '전투 체력 재생 8', '전투 중에 체력 재생의 $s1%가 작동하도록 허용합니다.'),
(51160, '전투 체력 재생 10', '전투 중에 체력 재생의 $s1%가 작동하도록 허용합니다.'),
(51161, '전투 체력 재생 15', '전투 중에 체력 재생의 $s1%가 작동하도록 허용합니다.'),
(51162, '전투 체력 재생 20', '전투 중에 체력 재생의 $s1%가 작동하도록 허용합니다.'),
(51163, '전투 체력 재생 25', '전투 중에 체력 재생의 $s1%가 작동하도록 허용합니다.'),
(51174, '공허 화살 발리슛', '암흑 마법의 투사체를 던져 근처 적들에게 암흑 피해를 입힙니다.'),
(51177, '신비한 폭발', '폭발적인 마법의 파도를 내보내 근처 적들에게 비전 피해를 입힙니다.'),
(51178, '마나비늘 지맥추적자 소환', '$d를 위해 당신을 보호해 줄 마나비늘 지맥 추적자를 소환합니다.'),
(51179, '마나비늘 새끼용 소환', '$d를 위해 당신을 보호해줄 $s1 마나비늘 새끼용을 소환합니다.'),
(51182, '유도된 지맥빔', '$t1초마다 선택한 지역의 적에게 $s1 비전 피해를 입힙니다. $d용.'),
(51183, '신비한 미사일', '적에게 신비한 미사일을 발사하여 $s1 비전 피해를 입힙니다.'),
(51184, '신비한 미사일', '적에게 신비한 미사일을 발사하여 $d에 대해 매초 $51183s1 비전 피해를 입힙니다.'),
(51185, '지맥 교란', '무작위 친화력을 소환합니다.'),
(51198, '네더볼트', '적에게 암흑 화살을 보내 $s1 암흑 피해를 입힙니다.'),
(51199, '형태 균열 정령', '시전자와 대상을 처치하고 균열 정령을 소환합니다.'),
(51201, '신비한 폭발', '폭발적인 마법의 파도를 내보내 근처 적들에게 비전 피해를 입힙니다.'),
(51208, '균열 소환-잃어버린 드레나이', '$d를 위해 당신을 보호해 줄 균열에서 사라진 드레나이를 소환합니다.'),
(51210, '폰의 전진', '$a1 야드 반경 내에 살아있는 폰 하나당 폰의 데미지가 $52666s1%만큼 증가합니다.'),
(51211, '앙파상', '$a1 야드 내의 모든 대상에게 $s1 물리 피해를 입힙니다.'),
(51212, '섀도우 볼트', '적에게 암흑 마법 화살을 던져 암흑 피해를 입힙니다.'),
(51213, '강화된 섀도우 볼트', '적에게 암흑 마법 화살을 던져 암흑 피해를 입힙니다.'),
(51214, '치유하다', '아군 대상의 체력을 완전히 회복시킵니다.'),
(51215, '섀도우 볼트 발리', '암흑 마법의 투사체를 던져 근처 적들에게 암흑 피해를 입힙니다.'),
(51216, '구속', '생명력과 마나의 $s1%로 죽은 생명체를 되살립니다.'),
(51220, '사전', '적에게 돌진하여 뒤로 밀쳐내고 $s3 피해를 입힙니다.'),
(51223, '공성 장비', '$51222s1 손상을 위해 폭발하는 화재 트랩을 설치하십시오. $d에는 트랩이 존재합니다.'),
(51225, '글로리어스 클리브', '적과 가장 가까운 아군에게 $s1 피해를 줍니다.'),
(51229, '왕의 분노', '시전자 주위에 성스러운 빛을 폭발시켜 $a1 야드 내의 모든 적 대상에게 $s1 신성 피해를 입힙니다.'),
(51233, '딱딱한 발톱', '$s1 피해를 입히고 적중한 대상 하나당 500의 추가 피해를 주는 전면 공격입니다.'),
(51235, '동상에 걸린 협곡', '플레이어 아래에 3초 후에 폭발하는 얼음 균열을 소환하여 그 안에 있는 플레이어를 8초 동안 얼려 냉기 피해를 입힙니다.'),
(51241, '조류의 흐름', '부상당한 아군에게 치유 에너지를 주입하여 근처의 다른 아군에게 전파합니다. 이 주문은 최대 $x1 대상에게 영향을 미치지만, 연속 대상마다 치유 에너지가 50%씩 감소합니다.'),
(51242, '홀리 스트라이크 크루세이더 스트라이크 쿨다운 감소', '신성한 일격과 성전사의 일격의 재사용 대기시간이 0.5초만큼 감소합니다.'),
(51244, '고블린 폭탄 소환', '가장 가까운 적에게 돌진하고 폭발하여 $51243s1 화염 피해를 주는 이동식 폭탄을 생성합니다.'),
(51245, '고블린 폭탄', '직접 피해를 주는 주문을 적중할 확률 5%로 가장 가까운 적에게 돌진하고 폭발하여 $51243s1 화염 피해를 주는 이동식 폭탄을 생성합니다.'),
(51247, '슬래그 폭발', '$51246s1 즉시 화염 피해를 입히고 $51246d보다 $51246o2 화염 피해를 입히기 위해 슬래그 볼트로 원거리 대상을 공격할 기회가 있습니다.'),
(51252, '캐스팅 재생 2%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.'),
(51253, '캐스팅 재생 3%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.'),
(51254, '캐스팅 재생 4%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.'),
(51255, '캐스팅 재생 6%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.'),
(51256, '캐스팅 재생 7%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.'),
(51257, '캐스팅 재생 8%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.')
INSERT INTO `locales_spell` (`entry`, `name_loc1`, `description_loc1`) VALUES
(51258, '캐스팅 재생 9%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.'),
(51259, '캐스팅 재생 11%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.'),
(51260, '캐스팅 재생 13%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.'),
(51261, '캐스팅 재생 14%', '시전하는 동안 $s1%의 마나 재생이 계속되도록 허용합니다.'),
(51264, '파이어볼트', '$s1 화염 피해를 위해 적을 폭파합니다.'),
(51265, '파이어볼트', '성공적인 근접 공격 시 $51264s1 화염 피해를 입힐 확률이 2%입니다.'),
(51268, '잔달라 감시 지속 효과', '착지 원거리 및 근접 공격은 5%의 확률로 $51267d에 대해 $51267s1만큼 민첩성을 증가시킵니다.'),
(51269, '스타파이어 감소된 시전 시간', 'Starfire의 시전 시간을 $/1000;S1초만큼 단축합니다.'),
(51272, '마카루의 지혜 지속 효과', '해로운 주문이 적중하면 $h%의 확률로 마카루의 지혜를 부여합니다. 마카루의 지혜 $51271u회 획득 시 깨달음 상태에 들어가 $51270d의 시전 속도가 $51270s1%만큼 증가합니다.'),
(51274, 'Frigid Blast 패시브', '적중 시 10% 확률로 $51273s2 냉기 피해를 입히고 $51273d1의 경우 공격자의 공격 및 이동 속도를 $51273s1%만큼 감소시킵니다. 최대 5번까지 중첩됩니다.'),
(51276, '냉동 콜드 패시브', '착지 공격과 해로운 주문은 각각 $h%와 10%의 확률로 대상을 동결시켜 $51275d에 대해 받는 화염 피해를 $51275s1%만큼 증가시킵니다.'),
(51278, '서리불꽃', '적에게 화염 피해를 입힙니다.'),
(51279, '서리불꽃', '적에게 냉기 피해를 입힙니다.'),
(51281, '서리불꽃 패시브', '착지 공격과 피해 주문은 대상에게 \'서리불꽃\'을 입힙니다. 대상이 서리불꽃에 걸리면 잠재된 에너지가 10배나 분출되어 대상에게 200의 화염 피해와 200의 냉기 피해를 입힙니다.'),
(51282, '엘룬의 낫 보너스', '주문의 적중률과 치명타 적중률이 $s1%만큼 향상됩니다. 마법 주문 및 효과로 인한 데미지를 최대 $s3만큼 증가시킵니다.'),
(51286, '녹아내린 파도', '적에게 돌진하여 $s2 화염 피해를 입히고 상대를 $d로 기절시킵니다.'),
(51287, '대지발구르기', '주변의 모든 적에게 $s1 물리 피해를 입힙니다.'),
(51292, '폭발하다', '주변 적들에게 $s1 자연 피해를 입히기 위해 시전자의 생명을 희생합니다.'),
(51295, '단편적인 분열', '적과 가장 가까운 아군에게 물리 피해를 입히고 최대 $x1 대상에게 영향을 미칩니다.'),
(51299, '개혁', '부서진 Rupturan을 재형성하기 위해 모든 조각을 희생합니다.'),
(51301, '맛있는 낚시 미끼', '낚싯대에 적용하면 $/60;s1분 동안 낚시가 $8085s1만큼 증가합니다.'),
(51323, '새벽', '아군을 치명적으로 치유하면 $51322d에 Daybreak가 적용됩니다. 아군이 피해를 입으면 Daybreak를 소모하여 $50931s1를 치유합니다.'),
(51362, '회개 패시브', '회개가 저항되거나 대상이 면역되면 대상은 자신의 죄를 회개하고 $51360d에 대한 해로운 주문을 공격하거나 시전할 때마다 $51361s1 신성 피해를 입습니다.'),
(51388, '낚시 숙련도 +125', '낚시 +$s1가 증가했습니다.'),
(51389, '간단한 낚시 미끼', '낚싯대에 적용하면 $/60;s1분 동안 낚시가 $8083s1만큼 증가합니다.'),
(51390, '매운 낚시 미끼', '낚싯대에 적용하면 $/60;s1분 동안 낚시가 $8084s1만큼 증가합니다.'),
(51396, '화염 유도', '이글거리는 마그마, 화염 폭발 토템의 치명타 피해 보너스가 $s3%만큼 증가합니다.  또한 이글거리는 토템과 화염 충격 주문의 범위가 $s2 야드만큼 증가하고 화염 충격을 시전하면 이글거리는 토템이 해당 대상에 집중하게 됩니다.'),
(51444, '이클립스', '자연 에너지와 아스트랄 에너지를 정렬합니다. 진노로 인한 피해는 $51444h%의 확률로 비전 일식을 부여하여 가하는 비전 피해를 증가시킵니다. 별빛의 피해는 $51445h%의 확률로 자연 일식을 부여하여 가하는 자연 피해를 증가시킵니다.\n\n피해 보너스는 $51443s1%에 주문 치명타 확률의 $s1%를 더한 것입니다. 각 효과는 $51443d 동안 지속되며 30초의 재사용 대기시간이 있습니다. 한 번에 하나의 Eclipse만 활성화할 수 있습니다.'),
(51445, '이클립스(아케인)', '자연 에너지와 아스트랄 에너지를 정렬합니다. 진노로 인한 피해는 $51444h%의 확률로 비전 일식을 부여하여 가하는 비전 피해를 증가시킵니다. 별빛의 피해는 $51445h%의 확률로 자연 일식을 부여하여 가하는 자연 피해를 증가시킵니다. 피해 보너스는 $51443s1%에 주문 치명타 확률의 $s1%를 더한 것입니다. 각 효과는 $51443d 동안 지속되며 30초의 재사용 대기시간이 있습니다. 한 번에 하나의 Eclipse만 활성화할 수 있습니다.'),
(51461, '지팡이 전문화', '$s1 마나를 회복합니다.'),
(51474, '계몽', '적을 폭발시켜 $s1 신성 피해를 줍니다.'),
(51475, '계몽 더미', 'Target of Enlighten은 이것을 시전자에게 다시 시전하여 대상을 Aura의 시전자로 저장합니다.'),
(51493, '해일', '$s1 마나를 회복합니다.'),
(51510, '호박', '따뜻한 오렌지색 코트를 입은 이 장난꾸러기 강아지는 항상 모험을 즐길 준비가 되어 있어 여러분의 여행에 활력을 불어넣어 줍니다.'),
(51511, '비스킷', '고상한 흑백 코트를 갖춘 이 코기는 우아함과 용기를 모두 발산하며 모든 모험가에게 완벽한 동맹자입니다.'),
(51541, 'Flametongue 무기 화재 피해 보너스', '$s1%만큼 화염 피해가 증가합니다.'),
(51578, '미리 계획하기 더미', '5초 동안 시전자에게 붙어있습니다.'),
(51586, '길들여지지 않은 사냥꾼', '제물의 함정과 폭발성 함정 효과의 마나 소모를 $s2%만큼 감소시키고 근접 공격력에 따라 공격력을 증가시킵니다. 또한 모든 함정은 전투 중에도 설치할 수 있습니다.'),
(51588, '드림사이트 젬', '에메랄드 드림에 대한 드림사이트(Dreamsight)를 얻으세요. 황혼의 숲에서만 작동합니다.'),
