INSERT INTO `locales_spell` (`entry`, `name_loc1`, `nameSubtext_loc1`, `description_loc1`, `auraDescription_loc1`) VALUES
(40707, '브라운 렌트 램', '임대 마운트', '간신히 의지하는 탈것을 소환하여 이동 속도를 40%만큼 증가시킵니다.', '늙고 심술궂고 어쩌면 두 번이나 은퇴했을 수도 있습니다. 뇌물을 받으면 앞으로 나아갑니다. 때로는 옆으로.\n\n속도가 40% 증가합니다.'),
(40708, '회색 임대 램', '임대 마운트', '간신히 의지하는 탈것을 소환하여 이동 속도를 40%만큼 증가시킵니다.', '늙고 심술궂고 어쩌면 두 번이나 은퇴했을 수도 있습니다. 뇌물을 받으면 앞으로 나아갑니다. 때로는 옆으로.\n\n속도가 40% 증가합니다.'),
(40709, '브라운 렌티드 코도', '임대 마운트', '간신히 의지하는 탈것을 소환하여 이동 속도를 40%만큼 증가시킵니다.', '늙고 심술궂고 어쩌면 두 번이나 은퇴했을 수도 있습니다. 뇌물을 받으면 앞으로 나아갑니다. 때로는 옆으로.\n\n속도가 40% 증가합니다.'),
(40710, '회색 임대 코도', '임대 마운트', '간신히 의지하는 탈것을 소환하여 이동 속도를 40%만큼 증가시킵니다.', '늙고 심술궂고 어쩌면 두 번이나 은퇴했을 수도 있습니다. 뇌물을 받으면 앞으로 나아갑니다. 때로는 옆으로.\n\n속도가 40% 증가합니다.'),
(40711, '임대된 탈라시안 유니콘', '임대 마운트', '간신히 의지하는 탈것을 소환하여 이동 속도를 40%만큼 증가시킵니다.', '늙고 심술궂고 어쩌면 두 번이나 은퇴했을 수도 있습니다. 뇌물을 받으면 앞으로 나아갑니다. 때로는 옆으로.\n\n속도가 40% 증가합니다.'),
(42002, '약화의 손길', '6단계', '시전자에 대한 다음 근접 공격은 $19254s1의 암흑 피해를 입히고 공격자가 입히는 피해를 $19254s2만큼 감소시켜 총 $19254d의 피해를 줍니다.', '다음으로 가해지는 근접 공격은 대상에게 피해를 주고 약화시킵니다.'),
(42035, '슬램', '랭크 1', '상대방을 강타하여 피해를 주지 않습니다.', '가짜 슬램 비주얼.'),
(42048, '징조의 룬', '랭크 1', '대상을 부패시켜 $d에 걸쳐 $o1 암흑 피해를 입힙니다.', '주기적으로 $s1 암흑 피해를 줍니다.'),
(45003, '숲의 수호자 형태', '장난감', '당신은 겉으로 보이는 그런 사람이 아닙니다.', '여성을 위한 무료 탑승.'),
(45017, '탈라시안 군마 소환', '소환', '탈것으로 사용할 수 있는 군마를 소환합니다. 속도는 탑승 기술에 따라 증가합니다.', '승마 기술 수준에 따라 속도가 증가합니다.'),
(45018, '은빛 군마 소환', '소환', '탈것으로 사용할 수 있는 군마를 소환합니다. 속도는 탑승 기술에 따라 증가합니다.', '승마 기술 수준에 따라 속도가 증가합니다.'),
(45019, '탈라시안 돌격마 소환', '소환', '탈것 역할을 하는 돌진마를 소환합니다. 속도는 탑승 숙련도에 따라 증가합니다.', '승마 기술 수준에 따라 속도가 증가합니다.'),
(45020, '은빛 돌격마 소환', '소환', '탈것 역할을 하는 돌진마를 소환합니다. 속도는 탑승 숙련도에 따라 증가합니다.', '승마 기술 수준에 따라 속도가 증가합니다.'),
(45028, '스칼렛 군마 소환', '소환', '탈것으로 사용할 수 있는 군마를 소환합니다. 속도는 탑승 기술에 따라 증가합니다.', '승마 기술 수준에 따라 속도가 증가합니다.'),
(45029, '스칼렛 차저 소환', '소환', '탈것 역할을 하는 돌진마를 소환합니다. 속도는 탑승 숙련도에 따라 증가합니다.', '승마 기술 수준에 따라 속도가 증가합니다.'),
(45400, '서리불꽃 화살', '1단계', '적에게 서리불꽃 화살을 발사하여 $s1의 냉기 및 화염 피해를 입히고, 이동 속도를 $s3% 감소시키며, $d초에 걸쳐 추가로 $s2의 화염 피해를 입힙니다. 이 주문은 대상의 냉기 및 화염 저항 중 더 낮은 수치를 기준으로 피해량을 확인합니다.', '$t2초마다 $s2의 화염 피해를 입힙니다.'),
(45409, '십자군 공격', '1단계', '$s2의 피해를 입히고, 성전사의 일격 1회당 대상이 받는 신성 피해를 최대 $s1까지 증가시키는 공격입니다. 최대 5회까지 적용할 수 있으며, 지속 시간은 $d입니다.', '신성 피해 받는 양이 최대 $s1까지 증가합니다.'),
(45410, '십자군 공격', '2단계', '$s2의 피해를 입히고, 성전사의 일격 1회당 대상이 받는 신성 피해를 최대 $s1까지 증가시키는 공격입니다. 최대 5회까지 적용할 수 있으며, 지속 시간은 $d입니다.', '신성 피해 받는 양이 최대 $s1까지 증가합니다.'),
(45411, '십자군 공격', '3단계', '$s2의 피해를 입히고, 성전사의 일격 1회당 대상이 받는 신성 피해를 최대 $s1까지 증가시키는 공격입니다. 최대 5회까지 적용할 수 있으며, 지속 시간은 $d입니다.', '신성 피해 받는 양이 최대 $s1까지 증가합니다.'),
(45412, '십자군 공격', '4단계', '$s2의 피해를 입히고, 성전사의 일격 1회당 대상이 받는 신성 피해를 최대 $s1까지 증가시키는 공격입니다. 최대 5회까지 적용할 수 있으며, 지속 시간은 $d입니다.', '신성 피해 받는 양이 최대 $s1까지 증가합니다.'),
(45413, '십자군 공격', '5단계', '$s2의 피해를 입히고, 성전사의 일격 1회당 대상이 받는 신성 피해를 최대 $s1까지 증가시키는 공격입니다. 최대 5회까지 적용할 수 있으며, 지속 시간은 $d입니다.', '신성 피해 받는 양이 최대 $s1까지 증가합니다.'),
(45500, '영혼의 연결', '1단계', '아군의 영혼을 15미터 이내의 다른 파티원들과 연결합니다. 대상이 피해를 입으면, 그 피해의 $s1%가 주변 아군에게 분배됩니다. $d 동안 지속됩니다.', '받은 피해의 $s1%를 그룹 구성원들과 분담합니다.'),
(45502, '에테르 형태', '1단계', '주술사가 받는 물리 피해를 $s1% 감소시키지만, $d% 동안 주문을 시전할 수 없게 됩니다.', '영혼과 함께 걷다.'),
(45503, '빅 배드 부두', '1단계', '정령의 힘을 빌려 주변 파티원들을 $d 동안 모든 피해와 효과에 면역으로 만듭니다. 시전자는 영향을 받지 않습니다.', '신나게 놀자!'),
(45504, '저주', '1단계', '적을 마법을 사용할 수 없는 개구리로 변신시키고, 최대 $d 동안 $s3%만큼 피해를 감소시킵니다. 야수, 인간형, 소형 생물에게만 효과가 있습니다.', '주문을 시전할 수 없으며, 받는 피해가 $s3% 감소합니다.'),
(45506, '지진', '1단계', '대상 지역에 강력한 지진을 일으켜 8미터 반경 내 적들에게 $t1초마다 $s1의 물리 피해를 입히고 이동 속도를 $s2% 감소시킵니다. $d 동안 지속됩니다. 주술사는 주문을 유지하기 위해 정신 집중을 해야 합니다.', '$t1초마다 $s1의 피해를 주고 이동 속도를 $s2% 감소시킵니다.'),
(45509, '피의 갈망', '1단계', '$r야드 이내의 대상 파티원의 근접, 원거리 및 주문 시전 속도를 $s1% 증가시킵니다. $d 동안 지속됩니다.', '근접, 원거리 및 주문 시전 속도가 $s1% 증가합니다.'),
(45511, '피의 갈망', '2단계', '$r야드 이내의 대상 파티원의 근접, 원거리 및 주문 시전 속도를 $s1% 증가시킵니다. $d 동안 지속됩니다.', '근접, 원거리 및 주문 시전 속도가 $s1% 증가합니다.'),
(45521, '폭풍 강타', '2단계', '추가 공격 기회를 얻습니다. 또한, 대상에게 가하는 다음 두 번의 자연 피해가 $s2% 증가합니다. $d 동안 지속됩니다.', '자연 피해 감소율 $s2% 증가.'),
(45525, '대지의 방패', '1단계', '시전자는 흙의 방패로 둘러싸여, 피해를 입을 때 주문 시전 방해를 $s2% 확률로 무시하고 공격 시 주술사의 생명력을 $45526s1만큼 회복시킵니다. 이 효과는 몇 초에 한 번씩만 발동합니다. 충전 횟수는 $n회이며, 지속 시간은 10분입니다. 주술사에게는 한 번에 하나의 정령 방패만 활성화될 수 있습니다.', '피를 입을 때 $s2% 확률로 주문 시전 방해를 무시하고 공격 시 주술사의 체력을 $45526s1 회복합니다.'),
(45527, '물의 방패', '1단계', '시전자는 $n개의 물구슬로 둘러싸여 있습니다. 주문, 근접 공격 또는 원거리 공격이 시전자를 공격할 때마다 마나 130이 회복됩니다. 이 과정에서 물구슬 하나가 소모됩니다. 몇 초에 한 번씩 물구슬이 하나씩만 활성화됩니다. 지속 시간은 $d회이며, 주술사에게는 한 번에 하나의 정령 방패만 활성화될 수 있습니다.', '자신에게 가해지는 공격과 주문 시 130의 마나를 회복합니다. $n 충전량.'),
(45529, '평온한 원소', '1단계', '대상을 진정시켜 공격 범위를 $s1야드 감소시킵니다. 레벨 $v 이하의 정령 대상에게만 효과가 있습니다. 지속 시간은 $d입니다.', '대상이 공격하는 거리가 줄어듭니다.'),
(45536, '치유의 비', '1단계', '대상 지역에 치유의 비를 뿌려 $d 이상의 파티원에게 $o1의 생명력을 회복시켜 줍니다.', '$t1초마다 $s1을 회복합니다.'),
(45551, '영혼의 기도', '2단계', '힘이 대상 파티에 스며들어 정신력을 $s1만큼 증가시킵니다($d).', '정신력을 $s1만큼 증가시킵니다.'),
(45555, '고통의 가시', '1단계', '즉시 $s1의 암흑 피해를 입히지만, 피해가 적중한 후 스스로 회복되기 시작합니다.', '일시적인 피해를 회복합니다.'),
(45564, '챔피언의 결속', '1단계', '사제와 용사 사이에 유대를 형성합니다. 사제가 피해를 입을 때 최대 $45570s2의 피해는 용사가 대신 입습니다. 지속 시간 $d.', '사제가 받는 최대 $45570s2의 피해는 대신 챔피언이 받습니다.'),
(45565, '챔피언 강화', '1단계', '대상 용사를 강화하여 주문 공격력을 최대 $s2, 공격력을 $s3만큼 증가시킵니다. 지속 시간 $d.', '모든 치유량과 주문 공격력이 최대 $s2만큼 증가하고 공격력은 $s3만큼 증가합니다.'),
(45570, '챔피언의 결속', '1단계', '이 주문은 사제의 용사가 사제에게 자동으로 시전해야 합니다.', '사제가 받는 최대 $s2의 피해는 대신 챔피언이 받습니다.'),
(45580, '지휘하는 외침', '1단계', '전사가 외칩니다. $a1야드 이내 모든 파티원의 최대 체력을 $s1만큼 회복합니다. 효과는 $d 동안 지속됩니다.', '최대 체력을 $s1만큼 증가시킵니다.'),
(45581, '뇌진탕 타격', '강화', '무기 피해를 입히고 상대를 $d만큼 기절시키는 강력한 일격입니다.', '기절했습니다.'),
(45582, '방패 경비병', '1단계', '방패로 아군 대상을 보호하여 모든 근접 및 원거리 공격의 $s1%가 자신에게 향하게 합니다. 대상은 전사로부터 $a1야드 이내에 있어야 합니다. 한 번에 하나의 방패 보호만 받을 수 있습니다. 전사는 한 번에 하나의 대상만 방패로 보호할 수 있습니다.', '경비 중.'),
(45586, '스톰볼트', '1단계', '적에게 $s1의 피해를 입히고 $d 동안 기절시킵니다.', '기절했습니다.'),
(45587, '칼날 폭풍', '1단계', '당신은 주변의 모든 적에게 $d의 무기 피해를 입히고, $t1초마다 추가로 $9633s1의 피해를 줍니다. 블레이드스톰 효과가 지속되는 동안에는 이동하거나 다른 능력을 사용할 수 없지만, 동정, 후회, 공포를 느끼지 않으며, 죽지 않는 한 멈출 수 없습니다.', '강철의 회오리바람으로 주변의 모든 적들을 공격합니다.'),
(45588, '칼날 폭풍', '2단계', '당신은 주변의 모든 적에게 $d의 무기 피해를 입히고, $t1초마다 추가로 $9633s1의 피해를 줍니다. 블레이드스톰 효과가 지속되는 동안에는 평소보다 $s3% 느리게 이동하지만, 다른 능력을 사용할 수 없으며, 동정, 후회, 공포를 느끼지 않으며, 죽지 않는 한 멈출 수 없습니다.', '강철의 회오리바람으로 주변의 모든 적들을 공격합니다.'),
(45592, '분쇄', '1단계', '근접 공격 시 30초 동안 주변 적에게 $45593s1의 피해를 줄 확률이 35%가 됩니다.', '근접 공격 대상 주변 지역에 물리 피해를 입힐 확률이 있습니다.'),
(45595, '개입하다', '1단계', '파티원을 향해 고속으로 달려가 다음 근접 또는 원거리 공격을 차단합니다.', '다음 근접 공격이나 원거리 공격은 당신을 향해 가해지는 대신, 그 사이에 있는 전사를 향해 가해질 것입니다.'),
(45599, '결정타', '1단계', '슬램(4단계)의 위력으로 상대를 결정적으로 공격하여 무기 공격력에 $11605s1을 추가합니다.', '이 능력의 디자인에 대한 모든 공로는 Wall of Wallcraft에게 있습니다.'),
(45604, '화려함', '1단계', '마무리 공격으로 패링 확률을 20% 추가로 증가시킵니다. 콤보 포인트당 지속 시간이 길어집니다.\r\n1포인트: 8초\r\n2포인트: 10초\r\n3포인트: 12초\r\n4포인트: 14초\r\n5포인트: 16초', '방어 성공 확률이 $s2% 증가했습니다.'),
(45607, '섬광탄', '1단계', '섬광 가루를 폭발시켜 주변의 모든 적의 시전 시간을 $d만큼 방해합니다.', '중단된.'),
(45617, '확신', '1단계', '치명타 확률을 $s1% 증가시킵니다.', '치명타 확률을 $s1% 증가시킵니다.')
INSERT INTO `locales_spell` (`entry`, `name_loc1`, `nameSubtext_loc1`, `description_loc1`, `auraDescription_loc1`) VALUES
(45618, '확신', '2단계', '치명타 확률을 $s1% 증가시킵니다.', '치명타 확률을 $s1% 증가시킵니다.'),
(45650, '늑대의 모습', '랭크 1', '사냥꾼은 늑대의 모습을 취하여 근접 공격력을 $s만큼 증가시키고 원거리 무기와 능력을 사용할 수 없게 됩니다. 한 번에 하나의 모습만 활성화할 수 있습니다.', '근접 공격력이 $s1 증가합니다.'),
(45653, '찢기', '1단계', '대상에게 상처를 입히고 근접 공격력의 $d을 초과하는 부분에 대해 21%의 출혈 피해를 줍니다.', '$t1초마다 출혈이 발생합니다.'),
(45654, '찢기', '2단계', '대상에게 $d을 초과하는 근접 공격력의 35%에 해당하는 출혈 피해를 입힙니다.', '$t1초마다 출혈이 발생합니다.'),
(45655, '찢기', '3단계', '대상에게 $d을 초과하는 근접 공격력의 49%에 해당하는 출혈 피해를 입힙니다.', '$t1초마다 출혈이 발생합니다.'),
(45659, '전갈의 일격', '1단계', '대상을 쏘아 힘과 민첩성을 $s1만큼 감소시키고 $d의 피해를 줍니다. 사냥꾼 한 명당 한 대상에게 한 번의 쏘기 공격만 사용할 수 있습니다.', '힘과 민첩성이 $s1 감소했습니다.'),
(45660, '독사의 일격', '1단계', '대상을 쏘아 $d에 걸쳐 $o1의 마나를 흡수합니다. 사냥꾼 한 명당 한 대상에게만 한 번의 쏘기 효과를 사용할 수 있습니다.', '$t1초마다 마나 $s1을 소모합니다.'),
(45661, '뱀의 일격', '1단계', '대상을 쏘아 $o1의 자연 피해를 $d에 걸쳐 입힙니다. 사냥꾼 한 명당 한 대상에게 한 번의 쏘기 공격만 활성화할 수 있습니다.', '$t1초마다 $s1의 자연 피해를 입힙니다.'),
(45664, '뱀의 모습', '1단계', '대부분의 원거리 및 근접 공격은 일정 확률로 $s1의 마나를 회복합니다.', '대부분의 공격으로부터 마나를 회복합니다.'),
(45705, '생명의 나무 형태', '변신', '생명의 나무로 변신합니다. 이 형태로 있는 동안 주변 파티원의 치유력이 자신의 정신력의 $45707s1%만큼 증가하고, 이동 속도가 $45706s2% 감소하며, 공격 주문이나 치유의 손길을 시전할 수 없지만, 지속 치유 주문의 마나 소모량이 20% 감소합니다.\r\n\r\n변신하는 행위는 변신 및 이동 속도 감소 효과에서 시전자를 해방합니다.', '변신 효과에 면역입니다.'),
(45740, '폭풍 까마귀 형태', '변신', '드루이드를 폭풍 까마귀 형태로 변신시킵니다. 폭풍 까마귀는 변신 상태에서만 조화 마법을 시전할 수 있습니다.\r\n\r\n변신하면 변신 마법과 이동 속도 감소 효과가 해제됩니다.', '변신 효과에 면역입니다.'),
(45802, '순교자의 인장', '1단계', '모든 근접 공격은 일반 무기 공격력의 $s1%에 해당하는 추가 신성 피해를 입히지만, 성기사는 입힌 총 피해량의 $s2%만큼 체력을 잃습니다.\r\n\r\n이 봉인의 에너지를 해방하면 적을 심판하여 즉시 $45816s1의 신성 피해를 입히지만, 입힌 피해량의 33%에 해당하는 체력을 잃습니다.', '근접 공격은 체력을 소모하는 대신 추가적인 신성 피해를 입힙니다.'),
(45910, '마나 깔때기', '1단계', '시전자가 정신 집중하는 동안 매초 시전자의 마나 $s1을 소환수 $ghis:her;로 옮깁니다.', '마나를 전송합니다.'),
(45911, '마나 깔때기', '2단계', '시전자가 정신 집중하는 동안 매초 시전자의 마나 $s1을 소환수 $ghis:her;로 옮깁니다.', '마나를 전송합니다.'),
(45915, '썩은 시체 떼', '1단계', '시전자 전방 원뿔형 범위 내 적들에게 악마 박쥐와 혼돈의 마법 파동을 방출하여 $s1의 암흑 피해를 주고, $t2초마다 추가로 $s2의 암흑 피해를 줍니다. $d에 대해.', '$t2초마다 $s2의 암흑 피해를 입습니다.'),
(45916, '아르키몬드의 저주 [PH]', '1단계', '대상의 지능을 $s1만큼 감소시키고 $t2초마다 $s2만큼 마나를 소모시키는 마법 저주입니다. 지속 시간은 $d입니다. 흑마법사 한 명당 하나의 대상에게만 저주를 걸 수 있습니다.', '지능이 $s1만큼 감소합니다.\r\n시전자는 $t2초마다 $s2의 마나를 소모합니다.'),
(45917, '마노로스의 저주 [PH]', '1단계', '대상의 공격 속도를 $s1%만큼 $d만큼 감소시킵니다. 흑마법사 한 명당 하나의 대상에게만 저주를 걸 수 있습니다.', '공격 속도가 $s1% 감소했습니다.'),
(45918, '사르게라스의 저주 [PH]', '1단계', '[PH]. 흑마법사 한 명당 하나의 대상에게만 저주를 걸 수 있습니다.', '[PH] $o1 그림자 피해가 $d를 초과합니다.'),
(45960, '결정타', '2단계', '강타(5단계)의 위력으로 상대를 결정적으로 공격하여 무기 공격력에 $45961s1을 추가합니다.', '이 능력의 디자인에 대한 모든 공로는 Wall of Wallcraft에게 있습니다.'),
(45961, '강타', '5단계', '상대를 내리쳐 무기 공격력에 $s1을 더한 피해를 줍니다.', '이것은 실제로 Slam을 가장한 Decisive Strike입니다.'),
(46003, '환영', '컬렉션', '외형을 변경합니다. 취소할 때까지 활성화됩니다.', '외형이 변경되었습니다.'),
(46015, '화학광', '종족 지속효과', '연금술 기술을 10만큼 증가시킵니다.', '"저는 화학에 완전 빠져있어요!"'),
(46019, '도망', '종족 특성', '탈출 전략의 보조 디버프로, 사용자를 $d 동안 진정시키고 침묵시킵니다.', '공격하거나 주문을 시전할 수 없습니다.'),
(46020, '숨이 차오름', '종족 특성', '탈출 전략의 초기 도주 및 이동 속도 증가 효과가 끝난 후 적용되는 이동 속도 감소 디버프입니다.', '이동 속도가 20% 감소했습니다.'),
(46021, '퀘르도레이 명상', '종족 특성', '이 주문을 시전하는 동안 5초 동안 초당 최대 마나의 $s1%, 분노 6 또는 에너지 $s3를 생성합니다.', '명상 중.'),
(46024, '회피', '지속효과', '소환된 악마가 광역 공격으로 받는 피해를 추가로 50% 감소시킵니다.', '효과 범위와 연쇄 공격으로 받는 피해가 감소합니다.'),
(46269, '화염 숨결', '1단계', '시전자 전방 원뿔형 범위 내의 대상은 $d에 걸쳐 ${$m1*3}의 화염 피해를 입습니다.', '초당 $s1의 화염 피해를 입힙니다.'),
(46270, '화염 숨결', '2단계', '시전자 전방 원뿔형 범위 내의 대상은 $d에 걸쳐 ${$m1*3}의 화염 피해를 입습니다.', '초당 $s1의 화염 피해를 입힙니다.'),
(46271, '독 침 뱉기', '1단계', '적에게 독을 뱉어 $d에 걸쳐 $o1의 자연 피해를 입힙니다.', '$t1초마다 자연 피해를 입힙니다.'),
(46272, '독 침 뱉기', '2단계', '적에게 독을 뱉어 $d에 걸쳐 $o1의 자연 피해를 입힙니다.', '$t1초마다 자연 피해를 입힙니다.'),
(46273, '독 침 뱉기', '3단계', '적에게 독을 뱉어 $d에 걸쳐 $o1의 자연 피해를 입힙니다.', '$t1초마다 자연 피해를 입힙니다.'),
(46282, '야만적인 찢기', '1단계', '랩터의 발톱으로 적을 베어 $s1의 피해를 주고, 대상에게 5초마다 $s2의 출혈 피해를 $d 동안 입힙니다.', '5초마다 물리 피해를 입힙니다.'),
(46283, '야만적인 찢기', '2단계', '랩터의 발톱으로 적을 베어 $s1의 피해를 주고, 대상에게 5초마다 $s2의 출혈 피해를 $d 동안 입힙니다.', '5초마다 물리 피해를 입힙니다.'),
(46284, '야만적인 찢기', '3단계', '랩터의 발톱으로 적을 베어 $s1의 피해를 주고, 대상에게 5초마다 $s2의 출혈 피해를 $d 동안 입힙니다.', '5초마다 물리 피해를 입힙니다.'),
(46285, '야만적인 찢기', '4단계', '랩터의 발톱으로 적을 베어 $s1의 피해를 주고, 대상에게 5초마다 $s2의 출혈 피해를 $d 동안 입힙니다.', '5초마다 물리 피해를 입힙니다.'),
(46286, '야만적인 찢기', '5단계', '랩터의 발톱으로 적을 베어 $s1의 피해를 주고, 대상에게 5초마다 $s2의 출혈 피해를 $d 동안 입힙니다.', '5초마다 물리 피해를 입힙니다.'),
(46292, '핀', '1단계', '대상을 제자리에 고정시키고 $d에 걸쳐 $o2의 피해를 주는 공격을 가합니다.', '시전자의 생명력을 매초 $s1씩 흡수합니다.'),
(46293, '핀', '2단계', '대상을 제자리에 고정시키고 $d에 걸쳐 $o2의 피해를 주는 공격을 가합니다.', '시전자의 생명력을 매초 $s1씩 흡수합니다.'),
(46294, '핀', '3단계', '대상을 제자리에 고정시키고 $d에 걸쳐 $o2의 피해를 주는 공격을 가합니다.', '시전자의 생명력을 매초 $s1씩 흡수합니다.'),
(46295, '핀', '4단계', '대상을 제자리에 고정시키고 $d에 걸쳐 $o2의 피해를 주는 공격을 가합니다.', '시전자의 생명력을 매초 $s1씩 흡수합니다.'),
(46296, '은총', '랭크 1', '회피 확률을 $s1%만큼 증가시킵니다(비용 $d).', '회피 확률을 $s1% 증가시킵니다.'),
(46788, '아에시나의 꽃', '랭크 1', '치유의 손길 주문의 시전 시간을 0.$/10;s2초만큼 줄이고 마나 비용의 $s1%를 돌려받습니다.', '치유의 손길 주문의 시전 시간을 0.$/10;s2초만큼 줄이고 마나 비용의 $s1%를 돌려받습니다.'),
(46789, '아에시나의 꽃', '랭크 2', '치유의 손길 주문의 시전 시간을 0.$/10;s2초만큼 줄이고 마나 비용의 $s1%를 돌려받습니다.', '치유의 손길 주문의 시전 시간을 0.$/10;s2초만큼 줄이고 마나 비용의 $s1%를 돌려받습니다.'),
(47384, '어둠의 권능: 고통', '랭크 1', '$a1 야드 반경 내의 모든 적에게 $o1 암흑 피해를 $d 이상으로 주는 어둠의 말씀입니다.', '$s1 $t1초마다 암흑 피해를 입힙니다.'),
(48001, '생명결속', '1단계', '$d에 걸쳐 대상에게 $o1의 피해를 회복시킵니다.', '$t1초마다 $s1의 피해를 치유합니다.'),
(48008, '피 흘리기', '1단계', '대상에게 $d에 걸쳐 100의 피해를 입히고 받는 치유량을 $s2% 감소시킵니다.', '출혈로 인한 피해량이 $o1이 되고, 치유 효과가 $s2% 감소합니다.'),
(48306, '지진', '랭크 1', '대상 아래의 대지를 부수어 대상에게 $s1 자연 피해를 입히고 $52878a1 야드 내의 다른 적들에게 해당 피해의 추가 $52878m1%를 자연 피해로 입힙니다. 내부의 적들을 $s2%만큼 느리게 만드는 부서진 땅 조각을 만듭니다. $d 이후, 부서진 대지가 여진으로 분출하여 해당 지역 내의 모든 적에게 초기 피해의 $51489m1%에 해당하는 자연 피해를 입힙니다.', '이동 속도가 $s2%만큼 감소합니다.'),
(48307, '지진', '랭크 2', '대상 아래의 대지를 부수어 대상에게 $s1 자연 피해를 입히고 $52878a1 야드 내의 다른 적들에게 해당 피해의 추가 $52878m1%를 자연 피해로 입힙니다. 내부의 적들을 $s2%만큼 느리게 만드는 부서진 땅 조각을 만듭니다. $d 이후, 부서진 대지가 여진으로 분출하여 해당 지역 내의 모든 적에게 초기 피해의 $51489m1%에 해당하는 자연 피해를 입힙니다.', '이동 속도가 $s2%만큼 감소합니다.'),
(48308, '지진', '랭크 3', '대상 아래의 대지를 부수어 대상에게 $s1 자연 피해를 입히고 $52878a1 야드 내의 다른 적들에게 해당 피해의 추가 $52878m1%를 자연 피해로 입힙니다. 내부의 적들을 $s2%만큼 느리게 만드는 부서진 땅 조각을 만듭니다. $d 이후, 부서진 대지가 여진으로 분출하여 해당 지역 내의 모든 적에게 초기 피해의 $51489m1%에 해당하는 자연 피해를 입힙니다.', '이동 속도가 $s2%만큼 감소합니다.'),
(50000, '슬로우 & 스테디', '도전', '적을 처치하여 얻는 경험치가 50% 감소합니다. 적에게 패배하면 현재 레벨에서 누적된 경험치의 5%를 잃습니다.', '느긋하게 지내고 있어요.')
INSERT INTO `locales_spell` (`entry`, `name_loc1`, `nameSubtext_loc1`, `description_loc1`, `auraDescription_loc1`) VALUES
(50001, '하드코어', '도전', '죽으면 당신의 영혼은 뒤틀린 황천으로 사라져 물질계로 다시 돌아올 수 없습니다.', '당신은 완전히 새롭게 태어났다고 생각해 보세요!'),
(50002, '생존주의자', '도전', '혹독한 환경에 더 쉽게 시달립니다. 생존하려면 굶주림, 갈증, 짐의 무게, 온도, 피로, 질병, 부상을 극복해야 합니다.', '불편함을 감수하며 지내는 중.'),
(50003, '트윙킹', '도전', '더 이상 어떤 경로로도 경험치를 얻지 못합니다.', '경험을 쌓지 못하고 있다.'),
(50004, '탈진', '도전', '더 이상 휴식 경험치를 획득하지 않습니다.', '평소처럼 느껴져요. 항상요.'),
(50006, '하드코어', '도전', '죽으면 당신의 영혼은 뒤틀린 황천으로 사라져 물질계로 다시 돌아올 수 없습니다.', '하드코어 챌린지를 활성화합니다.'),
(50007, '외로운 늑대', '도전', '다른 플레이어와의 거래 및 경매장 이용이 불가능합니다.\r\n\r\n다른 플레이어와 파티를 맺을 수 없습니다.\r\n\r\n장비를 제작할 수 없습니다.\r\n\r\n체력 회복 물약을 제외한 소모품을 사용할 수 없습니다.\r\n\r\n사망 시 묘지에서 자동으로 부활합니다.', '자신만의 길을 가는 중.'),
(50008, '전쟁 모드', '도전', '이제 PvP 모드를 비활성화할 수는 없지만, 모든 경로를 통한 경험치 및 명예 획득량이 20% 증가합니다.', 'PvP 영구 플래그 설정됨.'),
(50010, '구인!', '역할', '당신에게 $s1골드의 현상금이 걸렸습니다.', '현상금 $s1골드.'),
(50011, '현상금 사냥꾼', '역할', '무법자들을 추적하고 현상금을 획득하는 임무를 맡았습니다.', '무법자를 찾고 있다.'),
(50012, '피부 낭비', '도전', '너는 아무것도 아니야. 재능도 없고. 태어나지 말았어야 했어.', '끔찍해.'),
(50013, '데이 트레이더', '도전', '시간은 돈이다, 친구!\r\n\r\n-다른 플레이어와 아이템을 거래하거나 우편물을 받을 수 없습니다.\r\n\r\n-상인에게 판매한 아이템은 가치가 없습니다.', '탐욕은 좋은 것이다.'),
(50031, '[오라] 느리고 꾸준하게', '도전', '적을 처치하여 얻는 경험치가 50% 감소합니다. 적에게 패배하면 현재 레벨에서 누적된 경험치의 5%를 잃습니다.', '편하게 지내는 중. 테스트 중'),
(50032, '[오라] 하드코어', '도전', '죽으면 당신의 영혼은 뒤틀린 황천으로 사라져 물질계로 다시 돌아올 수 없습니다.', '하드코어하게 다시 태어났다고 생각해! 테스트 중'),
(50033, '[오라] 전쟁 모드', '도전', '더 이상 PvP를 비활성화할 수 없지만 모든 경험치 획득량이 증가합니다.', 'PvP 영구 플래그 설정됨. 테스트 중'),
(50034, '인페르노', '도전', '고난을 극복하며 불타오른 내면의 불꽃이 활활 타오르는 불길로 변했습니다. 당신이 죽으면 그 불꽃은 영원히 꺼질 것입니다.', '밝게 타오르는 빛.'),
(50035, '하드코어', '도전', '죽으면 당신의 영혼은 뒤틀린 황천으로 사라져 물질계로 다시 돌아올 수 없습니다.', '당신은 완전히 새롭게 태어났다고 생각해 보세요!'),
(50036, '생존주의자', '도전', '혹독한 환경에 더 쉽게 시달립니다. 생존하려면 굶주림, 갈증, 짐의 무게, 온도, 피로, 질병, 부상을 극복해야 합니다.', '불편함을 감수하며 지내는 중.'),
(50037, '트윙킹', '도전', '더 이상 어떤 경로로도 경험치를 얻지 못합니다.', '경험을 쌓지 못하고 있다.'),
(50038, '탈진', '도전', '더 이상 휴식 경험치를 획득하지 않습니다.', '평소처럼 느껴져요. 항상요.'),
(50039, '외로운 늑대', '도전', '다른 플레이어와의 거래 및 경매장 이용이 불가능합니다.\r\n\r\n다른 플레이어와 파티를 맺을 수 없습니다.\r\n\r\n장비를 제작할 수 없습니다.\r\n\r\n체력 회복 물약을 제외한 소모품을 사용할 수 없습니다.\r\n\r\n사망 시 묘지에서 자동으로 부활합니다.', '자신만의 길을 가는 중.'),
(50040, '전쟁 모드', '도전', '더 이상 PvP를 비활성화할 수 없지만 모든 경험치 획득량이 증가합니다.', 'PvP 영구 플래그 설정됨.'),
(50041, '구인!', '역할', '당신에게 $s1골드의 현상금이 걸렸습니다.', '현상금 $s1골드.'),
(50042, '현상금 사냥꾼', '역할', '무법자들을 추적하고 현상금을 획득하는 임무를 맡았습니다.', '무법자를 찾고 있다.'),
(50043, '피부 낭비', '도전', '너는 아무것도 아니야. 재능도 없고. 태어나지 말았어야 했어.', '끔찍해.'),
(50044, '데이 트레이더', '도전', '시간은 돈이다, 친구!\r\n\r\n-다른 플레이어와 아이템을 거래하거나 우편물을 받을 수 없습니다.\r\n\r\n-상인에게 판매한 아이템은 가치가 없습니다.', '탐욕은 좋은 것이다.'),
(50910, '환영: 지옥수호병', '장난감', '당신은 겉으로 보이는 그런 사람이 아닙니다.', '당신의 운명은 같을 것입니다.'),
(50917, '환영: 길니아스 늑대인간', '장난감', '당신은 겉으로 보이는 그런 사람이 아닙니다.', '나는 분노를 더 이상 참을 수 없습니다.'),
(50918, '환상: 좀비', '장난감', '당신은 겉으로 보이는 그런 사람이 아닙니다.', '허흠?'),
(50919, '환상: 구울', '장난감', '당신은 겉으로 보이는 그런 사람이 아닙니다.', '그래!'),
(50921, '환상: 인큐버스', '장난감', '당신은 겉으로 보이는 그런 사람이 아닙니다.', '당신의 욕망은 무엇입니까?'),
(51346, '의인의 보루', '랭크 1', '방패로 대상을 강타하여 $s1 신성 피해를 입히고 $d의 경우 받는 피해를 $s2%만큼 줄입니다.', '받는 데미지가 $s2%만큼 감소했습니다.'),
(51350, '신성한 힘', '랭크 1', '힘이 $s1%만큼 증가합니다.', '힘이 $s1%만큼 증가했습니다.'),
(51351, '신성한 힘', '랭크 2', '힘이 $s1%만큼 증가합니다.', '힘이 $s1%만큼 증가했습니다.'),
(51352, '신성한 힘', '랭크 3', '힘이 $s1%만큼 증가합니다.', '힘이 $s1%만큼 증가했습니다.'),
(51353, '신성한 힘', '랭크 4', '힘이 $s1%만큼 증가합니다.', '힘이 $s1%만큼 증가했습니다.'),
(51354, '신성한 힘', '랭크 5', '힘이 $s1%만큼 증가합니다.', '힘이 $s1%만큼 증가했습니다.'),
(51360, '회개하다', '랭크 1', '대상이 효과에 면역이면 죄를 회개하고 $d에 대한 근접 공격을 수행할 때마다 $51361s1 신성 피해를 입습니다.', '근접 공격을 할 때마다 피해를 입습니다.'),
(51397, '백화', '패시브', '재생 또는 회복 효과가 다른 드루이드로 대체될 때마다 즉시 남은 값의 $s1%만큼 치유됩니다.', '재생 또는 회복 효과가 다른 드루이드로 대체될 때마다 즉시 남은 값의 $s1%만큼 치유됩니다.'),
(51398, '신속한 여행 양식', '변신', '드루이드를 빠른 이동 형태로 변화시켜 이동 속도를 $51399s1%만큼 증가시킵니다.  또한 변이 효과로부터 시전자를 보호합니다.  실외 및 전투 중이 아닐 때만 사용할 수 있습니다.\n\n변신을 하면 시전자의 변이 및 이동 방해 효과가 해제됩니다.', '변이 효과에 면역입니다.  이동 속도가 $51399s1%만큼 증가했습니다.'),
(51401, '나무껍질(야생)', '랭크 1', '드루이드의 피부는 나무껍질처럼 단단해지며, 다음 $n 공격에서 받는 물리 피해를 $s1%만큼 감소시킵니다. 지속시간 동안 이동 속도가 $s2%만큼 감소합니다. $d 지속됩니다.', '받는 물리 피해가 $s1%만큼 감소합니다. 이동 속도가 $s2%만큼 감소합니다.'),
(51406, '야생의 아드레날린', '랭크 1', '다음에 회피할 때까지 회피 확률을 $s1%만큼 증가시킵니다.', '다음 번에 회피할 때까지 회피 확률이 $s1%만큼 증가합니다.'),
(51407, '야생의 아드레날린', '랭크 2', '다음에 회피할 때까지 회피 확률을 $s1%만큼 증가시킵니다.', '다음 번에 회피할 때까지 회피 확률이 $s1%만큼 증가합니다.'),
(51408, '야생의 아드레날린', '랭크 3', '다음에 회피할 때까지 회피 확률을 $s1%만큼 증가시킵니다.', '다음 번에 회피할 때까지 회피 확률이 $s1%만큼 증가합니다.'),
(51430, '월야수 변신', '변신', '드루이드를 달빛야수 형태로 변형합니다. 이 형태에서는 아이템의 방어구 기여도가 $51431s1%만큼 증가하고, 조화 주문의 마나 소모가 20%만큼 감소하며, 30야드 내의 모든 파티원의 주문 치명타 확률이 3%만큼 증가합니다. 달빛야수는 변신한 동안에만 균형 주문, 정신 자극, 저주 제거를 시전할 수 있습니다. 변신을 하면 시전자의 변이 및 이동 방해 효과가 해제됩니다.', '변이 효과에 면역입니다.  아이템의 방어구 기여도가 $51431s1%만큼 증가합니다.'),
(51438, '게일 윈즈', '랭크 1', '$d의 경우 대상의 공격 속도를 $s1%만큼 감소시킵니다.', '공격 속도가 $s1%만큼 감소합니다.'),
(51439, '게일 윈즈', '랭크 2', '$d의 경우 대상의 공격 속도를 $s1%만큼 감소시킵니다.', '공격 속도가 $s1%만큼 감소합니다.'),
(51451, '나무껍질(야생)', '랭크 2', '드루이드의 피부는 나무껍질처럼 단단해지며, 다음 $n 공격에서 받는 물리 피해를 $s1%만큼 감소시킵니다. 지속시간 동안 이동 속도가 $s2%만큼 감소합니다. $d 지속됩니다.', '받는 물리 피해가 $s1%만큼 감소합니다. 이동 속도가 $s2%만큼 감소합니다.'),
(51452, '나무껍질(야생)', '랭크 3', '드루이드의 피부는 나무껍질처럼 단단해지며, 다음 $n 공격에서 받는 물리 피해를 $s1%만큼 감소시킵니다. 지속시간 동안 이동 속도가 $s2%만큼 감소합니다. $d 지속됩니다.', '받는 물리 피해가 $s1%만큼 감소합니다. 이동 속도가 $s2%만큼 감소합니다.'),
(51478, '징벌하다', '랭크 1', '대상을 질책하여 $s1 신성 피해를 입힙니다.  대상이 적이라면 최대 $51569d 동안 또는 피해를 입을 때까지 방향 감각을 잃습니다.  대상이 아군인 경우 $51481d의 경우 공격 및 시전 속도가 $51481s1%만큼 증가하고, 피해로 인해 치명타가 발생하면 $52658d로 증가합니다.  체력이 80% 미만이거나 35레벨 미만인 아군에게는 사용할 수 없습니다.', '방향 감각을 잃었습니다.'),
(51479, '징벌하다', '랭크 2', '대상을 질책하여 $s1 신성 피해를 입힙니다.  대상이 적이라면 최대 $51569d 동안 또는 피해를 입을 때까지 방향 감각을 잃습니다.  대상이 아군인 경우 $51482d의 경우 공격 및 시전 속도가 $51482s1%만큼 증가하고, 피해로 인해 치명타가 발생하면 $52659d로 증가합니다.  체력이 80% 미만이거나 45레벨 이하인 아군에게는 사용할 수 없습니다.', '방향 감각을 잃었습니다.')
INSERT INTO `locales_spell` (`entry`, `name_loc1`, `nameSubtext_loc1`, `description_loc1`, `auraDescription_loc1`) VALUES
(51480, '징벌하다', '랭크 3', '대상을 질책하여 $s1 신성 피해를 입힙니다.  대상이 적이라면 최대 $51569d 동안 또는 피해를 입을 때까지 방향 감각을 잃습니다.  대상이 아군인 경우 $51483d의 경우 공격 및 시전 속도가 $51483s1%만큼 증가하고, 피해로 인해 치명타가 발생하면 $52660d로 증가합니다.  체력이 80% 미만이거나 55레벨 미만인 아군에게는 사용할 수 없습니다.', '방향 감각을 잃었습니다.'),
(51481, '징벌 가속', '랭크 1', '$d의 가속이 $s1%만큼 증가합니다.', '공격 속도와 시전 속도가 $s1%만큼 증가합니다.'),
(51482, '징벌 가속', '랭크 2', '$d의 가속이 $s1%만큼 증가합니다.', '공격 속도와 시전 속도가 $s1%만큼 증가합니다.'),
(51483, '징벌 가속', '랭크 3', '$d의 가속이 $s1%만큼 증가합니다.', '공격 속도와 시전 속도가 $s1%만큼 증가합니다.'),
(51496, '늑대의 상', '랭크 2', '사냥꾼은 늑대의 모습을 취하여 $s1만큼 근접 공격력을 증가시킵니다.  한 번에 하나의 측면만 활성화할 수 있습니다.', '$s1만큼 근접 공격력이 증가합니다.'),
(51497, '늑대의 상', '랭크 3', '사냥꾼은 늑대의 모습을 취하여 $s1만큼 근접 공격력을 증가시킵니다.  한 번에 하나의 측면만 활성화할 수 있습니다.', '$s1만큼 근접 공격력이 증가합니다.'),
(51498, '늑대의 상', '랭크 4', '사냥꾼은 늑대의 모습을 취하여 $s1만큼 근접 공격력을 증가시킵니다.  한 번에 하나의 측면만 활성화할 수 있습니다.', '$s1만큼 근접 공격력이 증가합니다.'),
(51499, '늑대의 상', '랭크 5', '사냥꾼은 늑대의 모습을 취하여 $s1만큼 근접 공격력을 증가시킵니다.  한 번에 하나의 측면만 활성화할 수 있습니다.', '$s1만큼 근접 공격력이 증가합니다.'),
(51500, '늑대의 상', '랭크 6', '사냥꾼은 늑대의 모습을 취하여 $s1만큼 근접 공격력을 증가시킵니다.  한 번에 하나의 측면만 활성화할 수 있습니다.', '$s1만큼 근접 공격력이 증가합니다.'),
(51501, '늑대의 상', '랭크 7', '사냥꾼은 늑대의 모습을 취하여 $s1만큼 근접 공격력을 증가시킵니다.  한 번에 하나의 측면만 활성화할 수 있습니다.', '$s1만큼 근접 공격력이 증가합니다.'),
(51509, '전갈침 피해 감소', '랭크 1', '전갈침의 피해 감소 효과는 주문의 무기 요구 사항 때문에 별도의 주문이어야 합니다. 그렇지 않으면 디버프는 원거리 피해에만 적용됩니다.', '물리 공격력이 $s1%만큼 감소했습니다.'),
(51520, '[더 이상 사용되지 않음] Trueshot Aura 백분율 보너스', '랭크 1', '$a1 야드 내의 파티원의 공격력을 $s1%만큼 증가시킵니다.  오라는 취소될 때까지 지속됩니다.', '공격력이 $s1%만큼 증가했습니다.'),
(51521, '[더 이상 사용되지 않음] Trueshot Aura 백분율 보너스', '랭크 2', '$a1 야드 내의 파티원의 공격력을 $s1%만큼 증가시킵니다.  오라는 취소될 때까지 지속됩니다.', '공격력이 $s1%만큼 증가했습니다.'),
(51522, '[더 이상 사용되지 않음] Trueshot Aura 백분율 보너스', '랭크 3', '$a1 야드 내의 파티원의 공격력을 $s1%만큼 증가시킵니다.  오라는 취소될 때까지 지속됩니다.', '공격력이 $s1%만큼 증가했습니다.'),
(51525, '어스 쉴드', '랭크 2', '캐스터는 $d용 보호 접지 $n 구체로 둘러싸여 있습니다. 주문, 근접 또는 원거리 공격이 시전자에게 적중하면 $51523s1 체력이 시전자에게 회복되어 구체 1개를 소비합니다. 이 효과는 3초에 한 번만 발생할 수 있습니다. 추가적으로 $s2%의 확률로 시전 중 데미지로 인한 방해를 피할 수 있습니다. 주술사는 한 번에 하나의 원소 보호막만 활성화할 수 있습니다.', '적중 시 $51523s1 체력을 회복하고 시전 중 피해로 인한 방해를 피할 확률이 $s2%만큼 증가합니다.'),
(51526, '어스 쉴드', '랭크 3', '캐스터는 $d용 보호 접지 $n 구체로 둘러싸여 있습니다. 주문, 근접 또는 원거리 공격이 시전자에게 적중하면 $51524s1 체력이 시전자에게 회복되어 구체 1개를 소비합니다. 이 효과는 3초에 한 번만 발생할 수 있습니다. 추가적으로 $s2%의 확률로 시전 중 데미지로 인한 방해를 피할 수 있습니다. 주술사는 한 번에 하나의 원소 보호막만 활성화할 수 있습니다.', '적중 시 $51524s1 체력을 회복하고 시전 중 피해로 인한 방해를 피할 확률이 $s2%만큼 증가합니다.'),
(51533, '워터쉴드', '랭크 2', '시전자는 $d의 활력을 되찾아주는 $n 구체로 둘러싸여 있습니다. 주문, 근접 또는 원거리 공격이 시전자에게 적중하면 $51529s1 마나가 시전자에게 회복되어 구체 1개를 소비합니다. 이 효과는 3초에 한 번만 발생할 수 있습니다. 주술사는 한 번에 하나의 원소 보호막만 활성화할 수 있습니다.', '적중 시 $51529s1의 마나를 회복합니다.'),
(51534, '워터쉴드', '랭크 3', '시전자는 $d의 활력을 되찾아주는 $n 구체로 둘러싸여 있습니다. 주문, 근접 또는 원거리 공격이 시전자에게 적중하면 $51530s1 마나가 시전자에게 회복되어 구체 1개를 소비합니다. 이 효과는 3초에 한 번만 발생할 수 있습니다. 주술사는 한 번에 하나의 원소 보호막만 활성화할 수 있습니다.', '적중 시 $51530s1의 마나를 회복합니다.'),
(51535, '워터쉴드', '랭크 4', '시전자는 $d를 위한 활력을 주는 물의 $n 구체로 둘러싸여 있습니다. 주문, 근접 또는 원거리 공격이 시전자에게 적중하면 $51531s1 마나가 시전자에게 회복되어 구체 1개를 소비합니다. 이 효과는 3초에 한 번만 발생할 수 있습니다. 주술사는 한 번에 하나의 원소 보호막만 활성화할 수 있습니다.', '적중 시 $51531s1의 마나를 회복합니다.'),
(51536, '워터쉴드', '랭크 5', '시전자는 $d의 활력을 되찾아주는 $n 구체로 둘러싸여 있습니다. 주문, 근접 또는 원거리 공격이 시전자에게 적중하면 $51532s1 마나가 시전자에게 회복되어 구체 1개를 소모합니다. 이 효과는 3초에 한 번만 발생할 수 있습니다. 주술사는 한 번에 하나의 원소 보호막만 활성화할 수 있습니다.', '적중 시 $51532s1의 마나를 회복합니다.'),
(51557, '회개', '랭크 2', '적 대상을 명상 상태에 빠뜨리고 최대 $d 동안 행동 불가 상태로 만듭니다.  피해를 입으면 대상이 깨어납니다.\n\n대상이 효과에 면역이면 죄를 회개하고 $51561d에 대한 근접 공격을 수행할 때마다 $51559s1 신성 피해를 입습니다.', '무능력함.'),
(51558, '회개', '랭크 3', '적 대상을 명상 상태에 빠뜨리고 최대 $d 동안 행동 불가 상태로 만듭니다.  피해를 입으면 대상이 깨어납니다.\n\n대상이 효과에 면역이면 죄를 회개하고 $51562d에 대한 근접 공격을 수행할 때마다 $51560s1 신성 피해를 입습니다.', '무능력함.'),
(51561, '회개하다', '랭크 2', '대상이 효과에 면역이면 죄를 회개하고 $d에 대한 근접 공격을 수행할 때마다 $51559s1 신성 피해를 입습니다.', '근접 공격을 할 때마다 피해를 입습니다.'),
(51562, '회개하다', '랭크 3', '대상이 효과에 면역이면 죄를 회개하고 $d에 대한 근접 공격을 수행할 때마다 $51560s1 신성 피해를 입습니다.', '근접 공격을 할 때마다 피해를 입습니다.'),
(51565, '의인의 보루', '랭크 2', '방패로 대상을 강타하여 $s1 신성 피해를 입히고 $d의 경우 받는 피해를 $s2%만큼 줄입니다.', '받는 데미지가 $s2%만큼 감소했습니다.'),
(51566, '의인의 보루', '랭크 3', '방패로 대상을 강타하여 $s1 신성 피해를 입히고 $d의 경우 받는 피해를 $s2%만큼 줄입니다.', '받는 데미지가 $s2%만큼 감소했습니다.'),
(51596, '향상된 쉴드 슬램', '랭크 1', '$d의 블록 확률이 $s1%만큼 증가합니다.', '블록 확률이 $s1%만큼 증가했습니다.'),
(51597, '향상된 쉴드 슬램', '랭크 2', '$d의 블록 확률이 $s1%만큼 증가합니다.', '블록 확률이 $s1%만큼 증가했습니다.'),
(51600, '뇌진탕 타격', '랭크 2', '$s2 대미지를 주고 상대를 $d로 기절시킵니다. 이 능력은 높은 위협 수준을 가하며 적 방어구를 100% 관통합니다. 즉시 $/10;s3 분노를 생성합니다.', '기절.'),
(51601, '뇌진탕 타격', '랭크 3', '$s2 대미지를 주고 상대를 $d로 기절시킵니다. 이 능력은 높은 위협 수준을 가하며 적 방어구를 100% 관통합니다. 즉시 $/10;s3 분노를 생성합니다.', '기절.'),
(51602, '뇌진탕 타격', '랭크 4', '$s2 대미지를 주고 상대를 $d로 기절시킵니다. 이 능력은 높은 위협 수준을 가하며 적 방어구를 100% 관통합니다. 즉시 $/10;s3 분노를 생성합니다.', '기절.'),
(51626, '반격', '랭크 1', '상대의 공격을 막아낸 후 활성화되는 공격입니다. 이 공격은 $s1 피해에 공격력의 10%를 더해 $d의 대상을 이동 불가 상태로 만듭니다. 반격은 막거나, 회피하거나, 막아낼 수 없습니다.', '움직이지 않습니다.'),
(51627, '반격', '랭크 2', '상대의 공격을 막아낸 후 활성화되는 공격입니다. 이 공격은 $s1 피해에 공격력의 10%를 더해 $d의 대상을 이동 불가 상태로 만듭니다. 반격은 막거나, 회피하거나, 막아낼 수 없습니다.', '움직이지 않습니다.'),
(51628, '반격', '랭크 3', '상대의 공격을 막아낸 후 활성화되는 공격입니다. 이 공격은 $s1 피해에 공격력의 10%를 더해 $d의 대상을 이동 불가 상태로 만듭니다. 반격은 막거나, 회피하거나, 막아낼 수 없습니다.', '움직이지 않습니다.'),
(51629, '반격', '랭크 4', '상대의 공격을 막아낸 후 활성화되는 공격입니다. 이 공격은 $s1 피해에 공격력의 10%를 더해 $d의 대상을 이동 불가 상태로 만듭니다. 반격은 막거나, 회피하거나, 막아낼 수 없습니다.', '움직이지 않습니다.'),
(51630, '반격', '랭크 5', '상대의 공격을 막아낸 후 활성화되는 공격입니다. 이 공격은 $s1 피해에 공격력의 10%를 더해 $d의 대상을 이동 불가 상태로 만듭니다. 반격은 막거나, 회피하거나, 막아낼 수 없습니다.', '움직이지 않습니다.'),
(51687, '영혼 배출', '랭크 5', '대상의 영혼을 흡수하여 $d에 $*6;s2 암흑 피해를 입힙니다.  대상이 에너지를 흡수한 상태에서 죽어 경험치나 명예를 얻으면 시전자는 영혼의 조각을 얻습니다.  다른 주문에는 영혼 조각이 필요합니다.', '$*6;s2 $d에 대한 암흑 피해.'),
(51706, '영혼 함정', '랭크 1', '당신이 조종하는 악마가 없는 동안, 입히는 모든 피해는 $s1%만큼 증가합니다.', '$s1%의 모든 공격력이 증가합니다.'),
(51707, '영혼 함정', '랭크 2', '당신이 조종하는 악마가 없는 동안, 입히는 모든 피해는 $s1%만큼 증가합니다.', '$s1%의 모든 공격력이 증가합니다.'),
(51708, '영혼 함정', '랭크 3', '당신이 조종하는 악마가 없는 동안, 입히는 모든 피해는 $s1%만큼 증가합니다.', '$s1%의 모든 공격력이 증가합니다.'),
